package com.ryanjei.orushio.pve.map;
import com.ryanjei.orushio.pve.domain.MapProfileId;import java.util.*;
public final class MapSelectionService {private final Random random;private MapProfileId fixedNext;public MapSelectionService(Random random){this.random=random;}public synchronized void fixNext(MapProfile profile){if(!profile.enabled())throw new IllegalStateException("無効なマップは次回固定できません。");fixedNext=profile.mapId();}public synchronized Optional<MapProfileId> fixedNext(){return Optional.ofNullable(fixedNext);}public synchronized void clearFixed(MapProfileId mapId){if(mapId.equals(fixedNext))fixedNext=null;}public synchronized MapProfile select(List<MapProfile> maps,MapProfileId previous){List<MapProfile> enabled=maps.stream().filter(MapProfile::enabled).toList();if(fixedNext!=null){MapProfileId wanted=fixedNext;MapProfile selected=enabled.stream().filter(m->m.mapId().equals(wanted)).findFirst().orElseThrow(()->new IllegalStateException("次回固定マップを利用できません。"));fixedNext=null;return selected;}if(enabled.isEmpty())throw new IllegalStateException("利用可能なマップがありません。");List<MapProfile> candidates=enabled;if(enabled.size()>1&&previous!=null)candidates=enabled.stream().filter(m->!m.mapId().equals(previous)).toList();return candidates.get(random.nextInt(candidates.size()));}}
